Definition w4s32_RcA_case : Prop :=
  forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x6 x7 x8 x9 x10 x12 x16 x17 x19 x20 x22 x23 x24 x26 x27 x28 x29 x30 x31 : word)
         (P SS n SBL SBH S2 L2 PTR PN U BITS PP PE DESC S3 : Z) (w224 : word),
    PTR = PN + U ->
    w4s_src_ctx RNG mm SS n SBL SBH ->
    n < 2^26 ->
    SS <= S2 ->
    S2 + L2 <= SS + n ->
    rw_cells asegs mm (P + 224) [C8 w224] ->
    rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] ->
    rw_cells asegs mm (P + 104) [C8 (Z_to_bv 64 DESC)] ->
    rw_cells asegs mm (P + 112) [C8 (Z_to_bv 64 S3)] ->
    rw_cells asegs mm (P + 200) [C8 (Z_to_bv 64 PE)] ->
    rng RNG P 496 ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    KXGoM.apart SS n P 496 ->
    S2 < PTR < S2 + 8 ->
    PTR - S2 + 8 <= L2 ->
    0 <= BITS <= 64 ->
    0 <= U <= 8 ->
    S2 <= PN ->
    0x60d000 <= PP ->
    PP < 2^47 ->
    0x60d000 <= PE + -3 ->
    PE <= 2^47 ->
    0 <= DESC < 2^64 ->
    0 <= S3 < 2^64 ->
    (PP < PE + -3 -> forall (mm' : amem) (cw : word) (y6 y8 y13 y14 y29 y30 : word),
       munch [(P + 224, P + 232)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 224) [C8 cw] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) y6 x7 y8 x9 x10 (Z_to_bv 64 PP) x12 y13 y14
           (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 (-8 * U + BITS)) x22 x23 x24 (Z_to_bv 64 PN)
           x26 x27 x28 y29 y30 cw) F (Z_to_bv 64 0x91f5c) fc None mm' (seg_rom asegs))) ->
    (PE + -3 <= PP -> forall (cw : word) (y6 y13 y14 y25 y30 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) y6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP)
           (Z_to_bv 64 PN) y13 y14 (Z_to_bv 64 PP) x16 x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 DESC) x22 x23 x24 y25
           x26 x27 (Z_to_bv 64 (-8 * U + BITS)) (Z_to_bv 64 PE) y30 cw) F (Z_to_bv 64 0x9232c) fc None mm (seg_rom
           asegs))) ->
